window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"fg-i1427":{src:"fig:idioms:1427",route:"#/figurative",cta:"More idioms",title:"Idiom · time flies",body:"time passes surprisingly quickly",source:"“Time flies at Grandma's — suddenly it's dinner and we never left the pillow fort.”"},"fg-i1428":{src:"fig:idioms:1428",route:"#/figurative",cta:"More idioms",title:"Idiom · tip of the tongue",body:"so close to remembering a word you can almost say it",source:"“Her name was on the tip of my tongue all through roll call.”"},"fg-i1429":{src:"fig:idioms:1429",route:"#/figurative",cta:"More idioms",title:"Idiom · best bib and tucker",body:"your smartest, fanciest clothes",source:"“Dad put on his best bib and tucker for the school awards night.”"},"fg-i1430":{src:"fig:idioms:1430",route:"#/figurative",cta:"More idioms",title:"Idiom · birthday suit",body:"bare skin; wearing no clothes at all",source:"“The toddler escaped bath time and ran down the hall in his birthday suit.”"},"fg-i1431":{src:"fig:idioms:1431",route:"#/figurative",cta:"More idioms",title:"Idiom · buckle down",body:"to start working hard and seriously",source:"“With the spelling bee a week away, Priya buckled down and drilled her word lists.”"},"fg-i1432":{src:"fig:idioms:1432",route:"#/figurative",cta:"More idioms",title:"Idiom · bursting at the seams",body:"so full there is no room for anything more",source:"“The gym was bursting at the seams for the district spelling bee.”"},"fg-i1433":{src:"fig:idioms:1433",route:"#/figurative",cta:"More idioms",title:"Idiom · button your lip",body:"to stop talking and keep a secret",source:"“Ben buttoned his lip about the surprise party for Grandma.”"},"fg-i1434":{src:"fig:idioms:1434",route:"#/figurative",cta:"More idioms",title:"Idiom · cap in hand",body:"asking for help humbly, like a beggar",source:"“After losing his bus money, Sam went cap in hand to his big sister.”"},"fg-i1435":{src:"fig:idioms:1435",route:"#/figurative",cta:"More idioms",title:"Idiom · cloak and dagger",body:"full of secrecy, spying, and mystery",source:"“The twins planned Mom's gift with cloak-and-dagger secrecy, passing notes under the table.”"},"fg-i1436":{src:"fig:idioms:1436",route:"#/figurative",cta:"More idioms",title:"Idiom · cut from whole cloth",body:"completely invented; utterly false",source:"“His excuse about a homework-eating parrot was cut from whole cloth.”"},"fg-i1437":{src:"fig:idioms:1437",route:"#/figurative",cta:"More idioms",title:"Idiom · dressed to kill",body:"wearing extremely stylish, show-stopping clothes",source:"“Aunt Rosa arrived at graduation dressed to kill in a bright red suit.”"},"fg-i1438":{src:"fig:idioms:1438",route:"#/figurative",cta:"More idioms",title:"Idiom · fill someone's shoes",body:"to take over someone's role and do it as well",source:"“When the team captain moved away, Zoe worked hard to fill her shoes.”"},"fg-i1439":{src:"fig:idioms:1439",route:"#/figurative",cta:"More idioms",title:"Idiom · in fine feather",body:"in excellent spirits or splendid condition",source:"“Grandpa was in fine feather at breakfast, telling jokes over his pancakes.”"},"fg-i1440":{src:"fig:idioms:1440",route:"#/figurative",cta:"More idioms",title:"Idiom · fit like a glove",body:"to fit perfectly",source:"“The rented spelling-bee blazer fit Marcus like a glove.”"},"fg-i1441":{src:"fig:idioms:1441",route:"#/figurative",cta:"More idioms",title:"Idiom · fly by the seat of your pants",body:"to act on instinct, without plans or instructions",source:"“Nobody explained the science-fair rules, so we flew by the seat of our pants.”"},"fg-i1442":{src:"fig:idioms:1442",route:"#/figurative",cta:"More idioms",title:"Idiom · get shirty",body:"to get cross or annoyed",source:"“Don't get shirty with me for pausing your game — it's homework time.”"},"fg-i1443":{src:"fig:idioms:1443",route:"#/figurative",cta:"More idioms",title:"Idiom · hand in glove",body:"working closely together, often in secret",source:"“The two class reps worked hand in glove to plan the bake sale.”"},"fg-i1444":{src:"fig:idioms:1444",route:"#/figurative",cta:"More idioms",title:"Idiom · handle with kid gloves",body:"to treat someone very gently and tactfully",source:"“After Mia's rough day at school, Dad handled her with kid gloves at dinner.”"},"fg-i1445":{src:"fig:idioms:1445",route:"#/figurative",cta:"More idioms",title:"Idiom · hang on to your hat",body:"get ready for something fast or surprising",source:"“Hang on to your hat — I got first place in the spelling bee!”"},"fg-i1446":{src:"fig:idioms:1446",route:"#/figurative",cta:"More idioms",title:"Idiom · hem and haw",body:"to stall and mumble instead of answering plainly",source:"“Asked who broke the vase, Theo hemmed and hawed until Mom raised an eyebrow.”"},"fg-i1447":{src:"fig:idioms:1447",route:"#/figurative",cta:"More idioms",title:"Idiom · hot under the collar",body:"angry, flustered, or embarrassed",source:"“Dad got hot under the collar when the printer jammed on my report — again.”"},"fg-i1448":{src:"fig:idioms:1448",route:"#/figurative",cta:"More idioms",title:"Idiom · if the shoe fits",body:"if a criticism applies to you, accept it",source:"“'Are you calling me messy?' Jake asked, and his sister shrugged: 'If the shoe fits.'”"},"fg-i1449":{src:"fig:idioms:1449",route:"#/figurative",cta:"More idioms",title:"Idiom · put yourself in someone else's shoes",body:"imagine how another person feels in their situation",source:"“Before laughing at the new student's mistake, put yourself in his shoes.”"},"fg-i1450":{src:"fig:idioms:1450",route:"#/figurative",cta:"More idioms",title:"Idiom · keep it under your hat",body:"keep it secret",source:"“I'm getting Mom a scarf for her birthday — keep it under your hat.”"},"fg-i1451":{src:"fig:idioms:1451",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your shirt on",body:"stay calm; don't lose your temper",source:"“Keep your shirt on — the pizza will be here in five minutes.”"},"fg-i1452":{src:"fig:idioms:1452",route:"#/figurative",cta:"More idioms",title:"Idiom · knock your socks off",body:"to amaze or impress you completely",source:"“Wait till you hear Ana's poem — it'll knock your socks off.”"},"fg-i1453":{src:"fig:idioms:1453",route:"#/figurative",cta:"More idioms",title:"Idiom · laugh up your sleeve",body:"to be secretly amused at someone",source:"“Rex pretended to sympathize, but he was laughing up his sleeve at the prank.”"},"fg-i1454":{src:"fig:idioms:1454",route:"#/figurative",cta:"More idioms",title:"Idiom · old hat",body:"so familiar it is boring or outdated",source:"“Long division is old hat to the fifth graders now.”"},"fg-i1455":{src:"fig:idioms:1455",route:"#/figurative",cta:"More idioms",title:"Idiom · pull up your socks",body:"make a real effort to improve",source:"“Coach told the relay team to pull up their socks before the county meet.”"},"fg-i1456":{src:"fig:idioms:1456",route:"#/figurative",cta:"More idioms",title:"Idiom · put a sock in it",body:"stop talking; be quiet",source:"“'Put a sock in it, you two,' Dad sighed from the front seat, 'or no radio.'”"},"fg-i1457":{src:"fig:idioms:1457",route:"#/figurative",cta:"More idioms",title:"Idiom · ride on someone's coattails",body:"to gain success from someone else's achievements",source:"“Don't ride on your lab partner's coattails — do your half of the project.”"},"fg-i1458":{src:"fig:idioms:1458",route:"#/figurative",cta:"More idioms",title:"Idiom · roll up your sleeves",body:"get ready to work hard",source:"“The whole family rolled up their sleeves to clean the garage on Saturday.”"},"fg-i1459":{src:"fig:idioms:1459",route:"#/figurative",cta:"More idioms",title:"Idiom · the shoe is on the other foot",body:"the situation is reversed; positions have swapped",source:"“Lily always quizzed her brother; now that she's in the bee, the shoe is on the other foot.”"},"fg-i1460":{src:"fig:idioms:1460",route:"#/figurative",cta:"More idioms",title:"Idiom · skirt the issue",body:"to avoid a difficult subject instead of facing it",source:"“When Mom asked about his math grade, Aiden skirted the issue by praising dinner.”"},"fg-i1461":{src:"fig:idioms:1461",route:"#/figurative",cta:"More idioms",title:"Idiom · take your hat off to",body:"to admire and respect someone's achievement",source:"“I take my hat off to anyone who can spell 'onomatopoeia' under pressure.”"},"fg-i1462":{src:"fig:idioms:1462",route:"#/figurative",cta:"More idioms",title:"Idiom · the emperor's new clothes",body:"something everyone praises though they secretly see it is fake",source:"“Everyone claimed the glitchy new app was amazing, but Dad called it the emperor's new clothes.”"},"fg-i1463":{src:"fig:idioms:1463",route:"#/figurative",cta:"More idioms",title:"Idiom · too big for your boots",body:"acting more important than you really are",source:"“Winning one quiz doesn't mean you can get too big for your boots.”"},"fg-i1464":{src:"fig:idioms:1464",route:"#/figurative",cta:"More idioms",title:"Idiom · wear the trousers",body:"to be the one in charge at home",source:"“Our cat clearly wears the trousers in this house — we all obey her meow.”"},"fg-i1465":{src:"fig:idioms:1465",route:"#/figurative",cta:"More idioms",title:"Idiom · white-collar",body:"relating to office work rather than manual labor",source:"“Mom's white-collar job means a desk, a computer, and far too many meetings.”"},"fg-i1466":{src:"fig:idioms:1466",route:"#/figurative",cta:"More idioms",title:"Idiom · blue-collar",body:"relating to manual or factory work",source:"“Grandpa is proud of his blue-collar years building bridges.”"},"fg-i1467":{src:"fig:idioms:1467",route:"#/figurative",cta:"More idioms",title:"Idiom · zip your lip",body:"stop talking and keep quiet",source:"“Zip your lip during the test, or the teacher will move your seat.”"},"fg-i1468":{src:"fig:idioms:1468",route:"#/figurative",cta:"More idioms",title:"Idiom · a month of Sundays",body:"a very long time",source:"“It'll take a month of Sundays to sort all these old family photos.”"},"fg-i1469":{src:"fig:idioms:1469",route:"#/figurative",cta:"More idioms",title:"Idiom · a race against time",body:"a scramble to finish before a deadline",source:"“Finishing the diorama before bedtime became a race against time.”"},"fg-i1470":{src:"fig:idioms:1470",route:"#/figurative",cta:"More idioms",title:"Idiom · against the clock",body:"rushing to finish before time runs out",source:"“We worked against the clock to hang decorations before the guests arrived.”"},"fg-i1471":{src:"fig:idioms:1471",route:"#/figurative",cta:"More idioms",title:"Idiom · ahead of your time",body:"having ideas too modern for your era",source:"“Great-Grandma coded computers in the 1960s — she was ahead of her time.”"},"fg-i1472":{src:"fig:idioms:1472",route:"#/figurative",cta:"More idioms",title:"Idiom · all in good time",body:"be patient; it will happen at the right moment",source:"“'When can I open presents?' 'All in good time — after cake.'”"},"fg-i1473":{src:"fig:idioms:1473",route:"#/figurative",cta:"More idioms",title:"Idiom · around the clock",body:"all day and all night without stopping",source:"“The animal shelter volunteers cared for the rescued puppies around the clock.”"},"fg-i1474":{src:"fig:idioms:1474",route:"#/figurative",cta:"More idioms",title:"Idiom · at the eleventh hour",body:"at the very last possible moment",source:"“Dev finished his book report at the eleventh hour, printing it as the bus arrived.”"},"fg-i1475":{src:"fig:idioms:1475",route:"#/figurative",cta:"More idioms",title:"Idiom · beat the clock",body:"to finish just before time runs out",source:"“Rosa beat the clock, bubbling in her last answer as the timer buzzed.”"},"fg-i1476":{src:"fig:idioms:1476",route:"#/figurative",cta:"More idioms",title:"Idiom · behind the times",body:"old-fashioned; unaware of modern ways",source:"“Dad still burns CDs for the car — he's a little behind the times.”"},"fg-i1477":{src:"fig:idioms:1477",route:"#/figurative",cta:"More idioms",title:"Idiom · big time",body:"the top, most successful level of anything",source:"“Making the national spelling bee means you've hit the big time.”"},"fg-i1478":{src:"fig:idioms:1478",route:"#/figurative",cta:"More idioms",title:"Idiom · call time on",body:"to declare something over",source:"“Mom called time on video games until everyone's homework was done.”"},"fg-i1479":{src:"fig:idioms:1479",route:"#/figurative",cta:"More idioms",title:"Idiom · carpe diem",body:"seize the day; make the most of today",source:"“'Carpe diem,' said Ms. Alvarez, 'sign up for the talent show today.'”"},"fg-i1480":{src:"fig:idioms:1480",route:"#/figurative",cta:"More idioms",title:"Idiom · day in, day out",body:"every single day, without variation",source:"“Day in, day out, Milo practices piano scales before school.”"},"fg-i1481":{src:"fig:idioms:1481",route:"#/figurative",cta:"More idioms",title:"Idiom · dog years",body:"a playful age scale where one human year counts as seven for dogs",source:"“Our beagle is nine, which Grandpa says makes her sixty-three in dog years.”"},"fg-i1483":{src:"fig:idioms:1483",route:"#/figurative",cta:"More idioms",title:"Idiom · down to the last minute",body:"continuing until the latest possible moment",source:"“Priya reviewed her spelling flashcards down to the last minute backstage.”"},"fg-i1484":{src:"fig:idioms:1484",route:"#/figurative",cta:"More idioms",title:"Idiom · five o'clock shadow",body:"the faint stubble on a man's face by late afternoon",source:"“By dinner Dad's five o'clock shadow makes his goodnight kiss scratchy.”"},"fg-i1485":{src:"fig:idioms:1485",route:"#/figurative",cta:"More idioms",title:"Idiom · for the time being",body:"for now, until things change",source:"“For the time being, the twins have to share a bedroom.”"},"fg-i1486":{src:"fig:idioms:1486",route:"#/figurative",cta:"More idioms",title:"Idiom · from day one",body:"from the very beginning",source:"“Coach said hustle matters from day one of practice.”"},"fg-i1487":{src:"fig:idioms:1487",route:"#/figurative",cta:"More idioms",title:"Idiom · have the time of your life",body:"to enjoy yourself tremendously",source:"“Maya had the time of her life at the class camping trip.”"},"fg-i1488":{src:"fig:idioms:1488",route:"#/figurative",cta:"More idioms",title:"Idiom · a heavy heart",body:"deep sadness, especially when doing something you wish you didn't have to",source:"“With a heavy heart, Mia handed back the library book she loved.”"},"fg-i1489":{src:"fig:idioms:1489",route:"#/figurative",cta:"More idioms",title:"Idiom · a leopard never changes its spots",body:"people cannot change their basic nature",source:"“Dad joked that our sock-stealing puppy proves a leopard never changes its spots.”"},"fg-i1490":{src:"fig:idioms:1490",route:"#/figurative",cta:"More idioms",title:"Idiom · at the end of your rope",body:"out of patience, energy, or options",source:"“After three broken shoelaces in one week, Mom was at the end of her rope.”"},"fg-i1491":{src:"fig:idioms:1491",route:"#/figurative",cta:"More idioms",title:"Idiom · at wit's end",body:"so worried or stuck you have no idea what to do next",source:"“After the tenth try at the math puzzle, Grandpa was at his wit's end.”"},"fg-i1492":{src:"fig:idioms:1492",route:"#/figurative",cta:"More idioms",title:"Idiom · bare your soul",body:"reveal your most private thoughts and feelings",source:"“In her diary, Ana bares her soul about spelling-bee nerves.”"},"fg-i1493":{src:"fig:idioms:1493",route:"#/figurative",cta:"More idioms",title:"Idiom · bent out of shape",body:"very upset or offended, usually over something small",source:"“Don't get bent out of shape over one wrong answer on the quiz.”"},"fg-i1494":{src:"fig:idioms:1494",route:"#/figurative",cta:"More idioms",title:"Idiom · beside yourself",body:"overwhelmed by a strong emotion like worry, anger, or joy",source:"“Grandma was beside herself with joy when Priya reached the final round.”"},"fg-i1495":{src:"fig:idioms:1495",route:"#/figurative",cta:"More idioms",title:"Idiom · bite your lip",body:"hold back words, laughter, or tears",source:"“Sam bit his lip to keep from blurting out the answer.”"},"fg-i1496":{src:"fig:idioms:1496",route:"#/figurative",cta:"More idioms",title:"Idiom · blow a fuse",body:"suddenly become very angry",source:"“Dad nearly blew a fuse when we left the freezer door open all night.”"},"fg-i1497":{src:"fig:idioms:1497",route:"#/figurative",cta:"More idioms",title:"Idiom · blow hot and cold",body:"keep changing your mind or enthusiasm",source:"“Lena blows hot and cold about joining the chess club.”"},"fg-i1498":{src:"fig:idioms:1498",route:"#/figurative",cta:"More idioms",title:"Idiom · blow your top",body:"explode with anger",source:"“Coach blew his top when nobody had practiced their word lists.”"},"fg-i1499":{src:"fig:idioms:1499",route:"#/figurative",cta:"More idioms",title:"Idiom · bottle up",body:"keep feelings shut inside instead of letting them out",source:"“The counselor said not to bottle up worries about the test.”"},"fg-i1500":{src:"fig:idioms:1500",route:"#/figurative",cta:"More idioms",title:"Idiom · burst with pride",body:"feel so proud you can hardly contain it",source:"“Mom nearly burst with pride when Ravi spelled 'chrysanthemum' perfectly.”"},"fg-i1501":{src:"fig:idioms:1501",route:"#/figurative",cta:"More idioms",title:"Idiom · carry the weight of the world",body:"feel burdened by enormous worries or responsibilities",source:"“Ever since tryouts, Maya has been carrying the weight of the world on her shoulders.”"},"fg-i1502":{src:"fig:idioms:1502",route:"#/figurative",cta:"More idioms",title:"Idiom · come apart at the seams",body:"fall apart emotionally, or stop working, under stress",source:"“By the third missed bus, our field-trip plan was coming apart at the seams.”"},"fg-i1503":{src:"fig:idioms:1503",route:"#/figurative",cta:"More idioms",title:"Idiom · cool your heels",body:"be kept waiting, usually longer than you'd like",source:"“We cooled our heels in the hallway while the judges tallied scores.”"},"fg-i1504":{src:"fig:idioms:1504",route:"#/figurative",cta:"More idioms",title:"Idiom · count your blessings",body:"notice and be thankful for the good things you have",source:"“When Zoe moaned about second place, Grandpa told her to count her blessings.”"},"fg-i1505":{src:"fig:idioms:1505",route:"#/figurative",cta:"More idioms",title:"Idiom · down in the mouth",body:"looking sad and discouraged",source:"“Leo was down in the mouth after fumbling his easiest word.”"},"fg-i1506":{src:"fig:idioms:1506",route:"#/figurative",cta:"More idioms",title:"Idiom · drive someone up the wall",body:"annoy or frustrate someone almost past bearing",source:"“My little brother's pencil-tapping drives me up the wall during homework.”"},"fg-i1507":{src:"fig:idioms:1507",route:"#/figurative",cta:"More idioms",title:"Idiom · fed up to the back teeth",body:"completely annoyed and out of patience",source:"“Mum is fed up to the back teeth with muddy shoes in the hallway.”"},"fg-i1508":{src:"fig:idioms:1508",route:"#/figurative",cta:"More idioms",title:"Idiom · feel blue",body:"feel sad or gloomy",source:"“Rainy Saturdays make me feel blue until we bake cookies.”"},"fg-i1509":{src:"fig:idioms:1509",route:"#/figurative",cta:"More idioms",title:"Idiom · feel on top of the world",body:"feel wonderfully happy and confident",source:"“After acing her recital, Nina felt on top of the world.”"},"fg-i1510":{src:"fig:idioms:1510",route:"#/figurative",cta:"More idioms",title:"Idiom · fit to be tied",body:"extremely angry or agitated",source:"“Dad was fit to be tied when the printer jammed on science-fair night.”"},"fg-i1511":{src:"fig:idioms:1511",route:"#/figurative",cta:"More idioms",title:"Idiom · fly into a rage",body:"suddenly become furiously angry",source:"“The villain in our class play flies into a rage over a stolen crown.”"},"fg-i1512":{src:"fig:idioms:1512",route:"#/figurative",cta:"More idioms",title:"Idiom · get carried away",body:"become so excited you lose control or good judgment",source:"“I got carried away decorating my book report and stayed up too late.”"},"fg-i1513":{src:"fig:idioms:1513",route:"#/figurative",cta:"More idioms",title:"Idiom · get it out of your system",body:"do or say something so the urge finally stops nagging you",source:"“Coach let us run a lap to get the giggles out of our system.”"},"fg-i1514":{src:"fig:idioms:1514",route:"#/figurative",cta:"More idioms",title:"Idiom · get on someone's nerves",body:"steadily annoy someone",source:"“Humming during silent reading gets on everyone's nerves.”"},"fg-i1515":{src:"fig:idioms:1515",route:"#/figurative",cta:"More idioms",title:"Idiom · get your knickers in a twist",body:"get flustered or upset over something minor",source:"“Don't get your knickers in a twist — we'll find your lucky pencil.”"},"fg-i1516":{src:"fig:idioms:1516",route:"#/figurative",cta:"More idioms",title:"Idiom · go to pieces",body:"lose emotional control completely",source:"“Practice the hard words now so you don't go to pieces on stage.”"},"fg-i1517":{src:"fig:idioms:1517",route:"#/figurative",cta:"More idioms",title:"Idiom · grin from ear to ear",body:"smile as widely as possible with delight",source:"“Tom grinned from ear to ear when his name made the finalist list.”"},"fg-i1518":{src:"fig:idioms:1518",route:"#/figurative",cta:"More idioms",title:"Idiom · have a screw loose",body:"be slightly crazy or act oddly",source:"“Our robot vacuum bumps the same wall all day, like it has a screw loose.”"},"fg-i1519":{src:"fig:idioms:1519",route:"#/figurative",cta:"More idioms",title:"Idiom · have a short fuse",body:"become angry very quickly",source:"“My sister has a short fuse when she's hungry, so we bring snacks.”"},"fg-i1520":{src:"fig:idioms:1520",route:"#/figurative",cta:"More idioms",title:"Idiom · have your heart set on",body:"want something so much you can't stop hoping for it",source:"“Ella has her heart set on winning the district bee.”"},"fg-i1521":{src:"fig:idioms:1521",route:"#/figurative",cta:"More idioms",title:"Idiom · hold a grudge",body:"keep resenting someone long after they wronged you",source:"“Ben doesn't hold a grudge; he congratulated the boy who beat him.”"},"fg-i1522":{src:"fig:idioms:1522",route:"#/figurative",cta:"More idioms",title:"Idiom · hopping mad",body:"so angry you could jump up and down",source:"“Mom was hopping mad when the twins tracked paint across the rug.”"},"fg-i1523":{src:"fig:idioms:1523",route:"#/figurative",cta:"More idioms",title:"Idiom · in a funk",body:"stuck in a gloomy, low mood",source:"“Losing his library card put Theo in a funk all afternoon.”"},"fg-i1524":{src:"fig:idioms:1524",route:"#/figurative",cta:"More idioms",title:"Idiom · in high spirits",body:"cheerful, lively, and energetic",source:"“The class was in high spirits on the last day before break.”"},"fg-i1525":{src:"fig:idioms:1525",route:"#/figurative",cta:"More idioms",title:"Idiom · in seventh heaven",body:"perfectly, blissfully happy",source:"“Ana was in seventh heaven when she got the top bunk at camp.”"},"fg-i1526":{src:"fig:idioms:1526",route:"#/figurative",cta:"More idioms",title:"Idiom · jump for joy",body:"be so happy you leap in the air",source:"“Milo jumped for joy when the snow day was announced.”"},"fg-i1527":{src:"fig:idioms:1527",route:"#/figurative",cta:"More idioms",title:"Idiom · keep a cool head",body:"stay calm and think clearly under pressure",source:"“Spellers who keep a cool head remember to ask for the word's origin.”"},"fg-i1528":{src:"fig:idioms:1528",route:"#/figurative",cta:"More idioms",title:"Idiom · keep your cool",body:"stay calm instead of getting upset",source:"“Even when the microphone squealed, Priya kept her cool.”"},"fg-i1529":{src:"fig:idioms:1529",route:"#/figurative",cta:"More idioms",title:"Idiom · laugh your head off",body:"laugh long and extremely hard",source:"“We laughed our heads off at Dad's upside-down pancake flip.”"},"fg-i1530":{src:"fig:idioms:1530",route:"#/figurative",cta:"More idioms",title:"Idiom · lose your cool",body:"get angry or flustered",source:"“The coach never loses his cool, even in overtime.”"},"fg-i1531":{src:"fig:idioms:1531",route:"#/figurative",cta:"More idioms",title:"Idiom · lose your temper",body:"suddenly become angry",source:"“I almost lost my temper when my block tower got knocked over.”"},"fg-i1532":{src:"fig:idioms:1532",route:"#/figurative",cta:"More idioms",title:"Idiom · make a scene",body:"cause a loud, embarrassing fuss in public",source:"“Please don't make a scene in the store over the cereal, buddy.”"},"fg-i1533":{src:"fig:idioms:1533",route:"#/figurative",cta:"More idioms",title:"Idiom · nerves of steel",body:"the ability to stay calm when things are frightening",source:"“It takes nerves of steel to spell the last word in a tiebreaker.”"},"fg-i1534":{src:"fig:idioms:1534",route:"#/figurative",cta:"More idioms",title:"Idiom · on edge",body:"nervous, tense, and easily startled",source:"“Everyone was on edge waiting for the results to be posted.”"},"fg-i1535":{src:"fig:idioms:1535",route:"#/figurative",cta:"More idioms",title:"Idiom · on tenterhooks",body:"in anxious suspense while you wait",source:"“We sat on tenterhooks while the judges checked the spelling.”"},"fg-i1536":{src:"fig:idioms:1536",route:"#/figurative",cta:"More idioms",title:"Idiom · out of sorts",body:"a little grumpy, unwell, or not yourself",source:"“Ben was out of sorts all morning until he finally ate breakfast.”"},"fg-i1537":{src:"fig:idioms:1537",route:"#/figurative",cta:"More idioms",title:"Idiom · pull yourself together",body:"calm down and regain control of your feelings",source:"“Take a deep breath, pull yourself together, and walk back on stage.”"},"fg-i1538":{src:"fig:idioms:1538",route:"#/figurative",cta:"More idioms",title:"Idiom · rant and rave",body:"shout and complain wildly and at length",source:"“Grandpa rants and raves at the TV referees every Saturday.”"},"fg-i1539":{src:"fig:idioms:1539",route:"#/figurative",cta:"More idioms",title:"Idiom · scared stiff",body:"so frightened you can't move",source:"“I was scared stiff during the thunderstorm until Mom lit candles.”"},"fg-i1540":{src:"fig:idioms:1540",route:"#/figurative",cta:"More idioms",title:"Idiom · take a load off your mind",body:"remove a worry that has been weighing on you",source:"“Finding the lost permission slip took a load off my mind.”"},"fg-i1541":{src:"fig:idioms:1541",route:"#/figurative",cta:"More idioms",title:"Idiom · take it easy",body:"relax; don't work or worry too hard",source:"“The doctor told Dad to take it easy for a week after his cold.”"},"fg-i1542":{src:"fig:idioms:1542",route:"#/figurative",cta:"More idioms",title:"Idiom · tear your hair out",body:"be wildly frustrated or worried",source:"“This maze puzzle has me tearing my hair out.”"},"fg-i1543":{src:"fig:idioms:1543",route:"#/figurative",cta:"More idioms",title:"Idiom · thin-skinned",body:"easily hurt or offended by criticism",source:"“Don't be thin-skinned about the coach's tips — they help.”"},"fg-i1544":{src:"fig:idioms:1544",route:"#/figurative",cta:"More idioms",title:"Idiom · tickled pink",body:"extremely pleased and delighted",source:"“Grandma was tickled pink to get a hand-drawn birthday card.”"},"fg-i1545":{src:"fig:idioms:1545",route:"#/figurative",cta:"More idioms",title:"Idiom · torn between",body:"unable to choose between two things you want equally",source:"“Rosa was torn between art club and the spelling team.”"},"fg-i1546":{src:"fig:idioms:1546",route:"#/figurative",cta:"More idioms",title:"Idiom · vent your spleen",body:"let out your anger and complaints",source:"“Dad vented his spleen about the traffic, then apologized for grumbling.”"},"fg-i1547":{src:"fig:idioms:1547",route:"#/figurative",cta:"More idioms",title:"Idiom · walking on air",body:"feeling so happy you seem weightless",source:"“Keisha was walking on air after spelling the winning word.”"},"fg-i1548":{src:"fig:idioms:1548",route:"#/figurative",cta:"More idioms",title:"Idiom · worried sick",body:"so worried you feel ill",source:"“Call home after practice so Mom isn't worried sick.”"},"fg-i1549":{src:"fig:idioms:1549",route:"#/figurative",cta:"More idioms",title:"Idiom · young at heart",body:"feeling and acting youthful whatever your age",source:"“Grandpa is young at heart — he still races us to the mailbox.”"},"fg-i1550":{src:"fig:idioms:1550",route:"#/figurative",cta:"More idioms",title:"Idiom · a play on words",body:"a joke built on a word's double meaning; a pun",source:"“Her project title, 'Gone with the Wind Power,' is a play on words.”"},"fg-i1551":{src:"fig:idioms:1551",route:"#/figurative",cta:"More idioms",title:"Idiom · actions, not words",body:"judge people by what they do, not what they promise",source:"“Coach wants actions, not words — practice, don't just promise to.”"},"fg-i1552":{src:"fig:idioms:1552",route:"#/figurative",cta:"More idioms",title:"Idiom · break the news",body:"be the one to tell someone important, often unhappy, information",source:"“Who's going to break the news that the field trip is postponed?”"},"fg-i1553":{src:"fig:idioms:1553",route:"#/figurative",cta:"More idioms",title:"Idiom · by the book",body:"strictly according to the rules",source:"“Our umpire calls every play by the book.”"},"fg-i1554":{src:"fig:idioms:1554",route:"#/figurative",cta:"More idioms",title:"Idiom · chew someone out",body:"scold someone loudly and harshly",source:"“The bus driver chewed us out for standing up before the stop.”"},"fg-i1555":{src:"fig:idioms:1555",route:"#/figurative",cta:"More idioms",title:"Idiom · clear the air",body:"talk honestly so tension or misunderstanding disappears",source:"“The sisters cleared the air about the borrowed headphones.”"},"fg-i1556":{src:"fig:idioms:1556",route:"#/figurative",cta:"More idioms",title:"Idiom · drop a hint",body:"suggest something indirectly, hoping someone catches on",source:"“Ana keeps dropping hints that she wants a dictionary for her birthday.”"},"fg-i1557":{src:"fig:idioms:1557",route:"#/figurative",cta:"More idioms",title:"Idiom · famous last words",body:"a teasing reply to a confident claim that may backfire",source:"“'This level is easy' — famous last words, said right before he lost.”"},"fg-i1558":{src:"fig:idioms:1558",route:"#/figurative",cta:"More idioms",title:"Idiom · get a word in edgewise",body:"manage to say anything while someone else talks nonstop",source:"“When the twins retell a movie, nobody gets a word in edgewise.”"},"fg-i1559":{src:"fig:idioms:1559",route:"#/figurative",cta:"More idioms",title:"Idiom · get straight to the point",body:"say the main thing immediately, without rambling",source:"“Our teacher gets straight to the point: 'Quiz Friday. Study.'”"},"fg-i1560":{src:"fig:idioms:1560",route:"#/figurative",cta:"More idioms",title:"Idiom · get the message",body:"understand what someone is really telling you",source:"“I yawned twice, and my chatty cousin finally got the message.”"},"fg-i1561":{src:"fig:idioms:1561",route:"#/figurative",cta:"More idioms",title:"Idiom · get the wrong end of the stick",body:"completely misunderstand a situation",source:"“Dad got the wrong end of the stick and arrived a day early for the recital.”"},"fg-i1562":{src:"fig:idioms:1562",route:"#/figurative",cta:"More idioms",title:"Idiom · give someone a piece of your mind",body:"angrily tell someone exactly what you think of them",source:"“Mom gave the prank callers a piece of her mind.”"},"fg-i1563":{src:"fig:idioms:1563",route:"#/figurative",cta:"More idioms",title:"Idiom · hear it through the grapevine",body:"learn news through gossip instead of official announcements",source:"“I heard it through the grapevine that our teacher is getting married.”"},"fg-i1564":{src:"fig:idioms:1564",route:"#/figurative",cta:"More idioms",title:"Idiom · hold your tongue",body:"stay silent even though you want to speak",source:"“I held my tongue about the surprise party all week.”"},"fg-i1565":{src:"fig:idioms:1565",route:"#/figurative",cta:"More idioms",title:"Idiom · in a manner of speaking",body:"in a certain way; sort of true",source:"“Our garage is a laboratory, in a manner of speaking, during science-fair week.”"},"fg-i1566":{src:"fig:idioms:1566",route:"#/figurative",cta:"More idioms",title:"Idiom · in black and white",body:"written or printed, so it is clear and official",source:"“The rules say it in black and white: no phones at the bee.”"},"fg-i1567":{src:"fig:idioms:1567",route:"#/figurative",cta:"More idioms",title:"Idiom · in plain English",body:"in simple, clear words anyone can understand",source:"“In plain English, 'photosynthesis' means plants making food from sunlight.”"},"fg-i1568":{src:"fig:idioms:1568",route:"#/figurative",cta:"More idioms",title:"Idiom · keep me posted",body:"keep telling me the latest news",source:"“Keep me posted on the bake sale — text me if you sell out.”"},"fg-i1569":{src:"fig:idioms:1569",route:"#/figurative",cta:"More idioms",title:"Idiom · keep mum",body:"say nothing; keep the secret",source:"“We're keeping mum about Dad's surprise gift.”"},"fg-i1570":{src:"fig:idioms:1570",route:"#/figurative",cta:"More idioms",title:"Idiom · lost in translation",body:"meaning that vanishes when words move between languages",source:"“Grandma's Hindi jokes get lost in translation, but we laugh anyway.”"},"fg-i1571":{src:"fig:idioms:1571",route:"#/figurative",cta:"More idioms",title:"Idiom · make small talk",body:"chat politely about unimportant things",source:"“Dad made small talk with the other parents while we rehearsed.”"},"fg-i1572":{src:"fig:idioms:1572",route:"#/figurative",cta:"More idioms",title:"Idiom · mince words",body:"soften your words instead of speaking bluntly",source:"“Our coach doesn't mince words: 'That spelling was sloppy.'”"},"fg-i1573":{src:"fig:idioms:1573",route:"#/figurative",cta:"More idioms",title:"Idiom · mum's the word",body:"keep this a secret; don't tell anyone",source:"“Mum's the word about Mom's surprise party until Saturday.”"},"fg-i1574":{src:"fig:idioms:1574",route:"#/figurative",cta:"More idioms",title:"Idiom · off the record",body:"said privately, not to be reported or repeated",source:"“Off the record, the coach thinks we'll win districts.”"},"fg-i1575":{src:"fig:idioms:1575",route:"#/figurative",cta:"More idioms",title:"Idiom · on record",body:"stated publicly and officially, where it can be checked",source:"“The principal is on record promising a pizza party for perfect attendance.”"},"fg-i1576":{src:"fig:idioms:1576",route:"#/figurative",cta:"More idioms",title:"Idiom · put in a good word",body:"say something nice about someone to help them",source:"“Will you put in a good word for me with the librarian?”"},"fg-i1577":{src:"fig:idioms:1577",route:"#/figurative",cta:"More idioms",title:"Idiom · put words in someone's mouth",body:"claim someone said things they never actually said",source:"“Don't put words in my mouth — I said maybe, not yes.”"},"fg-i1578":{src:"fig:idioms:1578",route:"#/figurative",cta:"More idioms",title:"Idiom · read between the lines",body:"notice the hidden meaning that isn't stated directly",source:"“Reading between the lines of her note, I could tell she was nervous.”"},"fg-i1579":{src:"fig:idioms:1579",route:"#/figurative",cta:"More idioms",title:"Idiom · run your mouth",body:"talk too much, often carelessly or boastfully",source:"“He ran his mouth about winning, then went out in round one.”"},"fg-i1580":{src:"fig:idioms:1580",route:"#/figurative",cta:"More idioms",title:"Idiom · speak of the devil",body:"said when someone appears just as you mention them",source:"“Speak of the devil — we were just talking about you, Uncle Raj!”"},"fg-i1581":{src:"fig:idioms:1581",route:"#/figurative",cta:"More idioms",title:"Idiom · speak volumes",body:"reveal a great deal without any words",source:"“Her grin when the results went up spoke volumes.”"},"fg-i1582":{src:"fig:idioms:1582",route:"#/figurative",cta:"More idioms",title:"Idiom · spell it out",body:"explain something in the plainest, most detailed way",source:"“Do I have to spell it out? Muddy cleats stay outside.”"},"fg-i1583":{src:"fig:idioms:1583",route:"#/figurative",cta:"More idioms",title:"Idiom · spread the word",body:"tell everyone the news",source:"“Spread the word: the bake sale moved to Friday.”"},"fg-i1584":{src:"fig:idioms:1584",route:"#/figurative",cta:"More idioms",title:"Idiom · straight talk",body:"honest, direct speech with no tricks",source:"“Time for some straight talk: homework comes before video games.”"},"fg-i1585":{src:"fig:idioms:1585",route:"#/figurative",cta:"More idioms",title:"Idiom · take my word for it",body:"believe me without demanding proof",source:"“Take my word for it — the cafeteria chili is spicy today.”"},"fg-i1586":{src:"fig:idioms:1586",route:"#/figurative",cta:"More idioms",title:"Idiom · talk a mile a minute",body:"talk extremely fast",source:"“After camp, Zoe talked a mile a minute about the canoe race.”"},"fg-i1587":{src:"fig:idioms:1587",route:"#/figurative",cta:"More idioms",title:"Idiom · talk in circles",body:"talk on and on without ever reaching the point",source:"“Quit talking in circles and tell us who won.”"},"fg-i1588":{src:"fig:idioms:1588",route:"#/figurative",cta:"More idioms",title:"Idiom · talk shop",body:"discuss your work when you're not at work",source:"“At the picnic, the two teachers ended up talking shop about grading.”"},"fg-i1589":{src:"fig:idioms:1589",route:"#/figurative",cta:"More idioms",title:"Idiom · talk the talk",body:"speak impressively about something, whether or not you can actually do it",source:"“He talks the talk about chess, but he's never beaten Grandma.”"},"fg-i1590":{src:"fig:idioms:1590",route:"#/figurative",cta:"More idioms",title:"Idiom · talk through your teeth",body:"say something you know is false; lie boldly",source:"“He was talking through his teeth when he claimed his book report was done.”"},"fg-i1591":{src:"fig:idioms:1591",route:"#/figurative",cta:"More idioms",title:"Idiom · tell it like it is",body:"speak the plain truth, even when it's uncomfortable",source:"“Grandma tells it like it is: 'Your room is a disaster.'”"},"fg-i1592":{src:"fig:idioms:1592",route:"#/figurative",cta:"More idioms",title:"Idiom · the last word",body:"the final remark in an argument; also the newest, finest version of something",source:"“My sister always needs the last word, even in whispers.”"},"fg-i1593":{src:"fig:idioms:1593",route:"#/figurative",cta:"More idioms",title:"Idiom · walk the talk",body:"back up your words with matching actions",source:"“She says practice matters, and she walks the talk — twenty words every morning.”"},"fg-i1594":{src:"fig:idioms:1594",route:"#/figurative",cta:"More idioms",title:"Idiom · word for word",body:"repeated or copied in exactly the same words",source:"“Leo memorized the whole poem word for word.”"},"fg-i1595":{src:"fig:idioms:1595",route:"#/figurative",cta:"More idioms",title:"Idiom · words fail me",body:"I'm too amazed, moved, or shocked to speak",source:"“Words fail me — you cleaned the whole kitchen without being asked!”"},"fg-i1596":{src:"fig:idioms:1596",route:"#/figurative",cta:"More idioms",title:"Idiom · zip it",body:"stop talking right now",source:"“The librarian's look said 'zip it' better than any words.”"},"fg-i1597":{src:"fig:idioms:1597",route:"#/figurative",cta:"More idioms",title:"Idiom · an A for effort",body:"credit for trying hard, even though the attempt failed",source:"“The lopsided birthday cake earned Dad an A for effort.”"},"fg-i1598":{src:"fig:idioms:1598",route:"#/figurative",cta:"More idioms",title:"Idiom · all in a day's work",body:"a normal part of the job, even if hard or surprising",source:"“Untangling three kites at once? All in a day's work for Grandpa.”"},"fg-i1599":{src:"fig:idioms:1599",route:"#/figurative",cta:"More idioms",title:"Idiom · back to the grind",body:"returning to hard, repetitive work",source:"“Vacation's over — back to the grind of word lists and math facts.”"},"fg-i1600":{src:"fig:idioms:1600",route:"#/figurative",cta:"More idioms",title:"Idiom · back to the salt mines",body:"returning to hard, unpleasant work, said as a joke",source:"“Recess is over — back to the salt mines, spellers!”"},"fg-i1601":{src:"fig:idioms:1601",route:"#/figurative",cta:"More idioms",title:"Idiom · to have a stick in your ear",body:"to have had too much to drink",source:"“Uncle Lars danced so wildly at the wedding that Grandma joked he had a stick in his ear.”"},"fg-i1602":{src:"fig:idioms:1602",route:"#/figurative",cta:"More idioms",title:"Idiom · to walk around hot porridge",body:"to avoid the real subject instead of speaking directly",source:"“Stop walking around hot porridge and just tell Mom about the math test.”"},"fg-i1603":{src:"fig:idioms:1603",route:"#/figurative",cta:"More idioms",title:"Idiom · to feed the donkey sponge cake",body:"to waste something fine on someone who won't appreciate it",source:"“Buying fancy gel pens for my little brother is feeding the donkey sponge cake — he just chews them.”"},"fg-i1604":{src:"fig:idioms:1604",route:"#/figurative",cta:"More idioms",title:"Idiom · to have the cockroach",body:"to feel sad and gloomy",source:"“Rainy Sundays with nobody to play with give me the cockroach.”"},"fg-i1605":{src:"fig:idioms:1605",route:"#/figurative",cta:"More idioms",title:"Idiom · a mouse's child will be a mouse",body:"children usually turn out like their parents",source:"“Dad the old champion speller grinned 'a mouse's child will be a mouse' when I made the school bee final.”"},"fg-i1606":{src:"fig:idioms:1606",route:"#/figurative",cta:"More idioms",title:"Idiom · drop by drop a lake forms",body:"small steady efforts add up to something big",source:"“Learn five spelling words a day — drop by drop a lake forms.”"},"fg-i1607":{src:"fig:idioms:1607",route:"#/figurative",cta:"More idioms",title:"Idiom · to have your butt between two chairs",body:"to be awkwardly stuck between two choices or two worlds",source:"“With soccer and choir both meeting on Tuesdays, I've got my butt between two chairs.”"},"fg-i1608":{src:"fig:idioms:1608",route:"#/figurative",cta:"More idioms",title:"Idiom · not to be out of the inn",body:"to still face plenty of trouble before a problem is over",source:"“Two posters done and eight to go — our project group is not out of the inn yet.”"},"fg-i1609":{src:"fig:idioms:1609",route:"#/figurative",cta:"More idioms",title:"Idiom · to push grandma into the nettles",body:"to push your luck or take something too far",source:"“Extra dessert AND a later bedtime? Don't push grandma into the nettles.”"},"fg-i1610":{src:"fig:idioms:1610",route:"#/figurative",cta:"More idioms",title:"Idiom · to take someone's hair",body:"to tease someone playfully or fool them",source:"“You did NOT meet the national spelling champion at the mall — you're taking my hair!”"},"fg-i1611":{src:"fig:idioms:1611",route:"#/figurative",cta:"More idioms",title:"Idiom · the drop that made the barrel overflow",body:"the small final problem that makes everything too much",source:"“The broken pencil was the drop that made the barrel overflow, and Mia burst into tears over her homework.”"},"fg-i1612":{src:"fig:idioms:1612",route:"#/figurative",cta:"More idioms",title:"Idiom · after the birds",body:"too late; the chance has already passed",source:"“We reached the bake sale after the birds — every last cookie was gone.”"},"fg-i1613":{src:"fig:idioms:1613",route:"#/figurative",cta:"More idioms",title:"Idiom · don't call the wolf from the forest",body:"don't invite trouble by talking about it",source:"“Don't brag that you never lose your backpack — don't call the wolf from the forest.”"},"fg-i1614":{src:"fig:idioms:1614",route:"#/figurative",cta:"More idioms",title:"Idiom · to throw peas at a wall",body:"to waste words on someone who won't listen",source:"“Telling my brother to clean his desk is throwing peas at a wall.”"},"fg-i1615":{src:"fig:idioms:1615",route:"#/figurative",cta:"More idioms",title:"Idiom · to return with Hunayn's slippers",body:"to come back empty-handed and outsmarted",source:"“I waited an hour in the book-fair line and returned with Hunayn's slippers — they had sold out.”"},"fg-i1616":{src:"fig:idioms:1616",route:"#/figurative",cta:"More idioms",title:"Idiom · to eat the earth",body:"to fall down hard",source:"“I ate the earth on the icy playground but got right back up.”"},"fg-i1617":{src:"fig:idioms:1617",route:"#/figurative",cta:"More idioms",title:"Idiom · strike gold",body:"to find sudden success or something very valuable",source:"“We struck gold when Grandpa turned out to be a walking dictionary.”"},"fg-i1618":{src:"fig:idioms:1618",route:"#/figurative",cta:"More idioms",title:"Idiom · take stock",body:"to pause and carefully assess a situation",source:"“After the practice test, we took stock of which word lists still needed work.”"},"fg-i1619":{src:"fig:idioms:1619",route:"#/figurative",cta:"More idioms",title:"Idiom · the buck stops here",body:"the final responsibility is mine and cannot be passed on",source:"“Dad says the buck stops here when the carpool plan goes wrong.”"},"fg-i1620":{src:"fig:idioms:1620",route:"#/figurative",cta:"More idioms",title:"Idiom · throw money at the problem",body:"to try to fix something by spending, without real thought",source:"“Buying five spelling apps is just throwing money at the problem; you still have to practice.”"},"fg-i1621":{src:"fig:idioms:1621",route:"#/figurative",cta:"More idioms",title:"Idiom · tighten the purse strings",body:"to cut back on spending",source:"“After the car repair, Mom tightened the purse strings on weekend treats.”"},"fg-i1622":{src:"fig:idioms:1622",route:"#/figurative",cta:"More idioms",title:"Idiom · time is money",body:"wasted time costs you as much as wasted money",source:"“Dad taped 'time is money' above my desk during exam week.”"},"fg-i1623":{src:"fig:idioms:1623",route:"#/figurative",cta:"More idioms",title:"Idiom · two cents' worth",body:"your opinion, offered humbly",source:"“Can I add my two cents' worth about the carpool schedule?”"},"fg-i1624":{src:"fig:idioms:1624",route:"#/figurative",cta:"More idioms",title:"Idiom · worth its weight in gold",body:"extremely valuable or useful",source:"“A quiet study corner is worth its weight in gold before a bee.”"},"fg-i1625":{src:"fig:idioms:1625",route:"#/figurative",cta:"More idioms",title:"Idiom · cash on the barrelhead",body:"immediate payment, on the spot",source:"“The yard-sale lady wanted cash on the barrelhead, so Dad counted out bills.”"},"fg-i1626":{src:"fig:idioms:1626",route:"#/figurative",cta:"More idioms",title:"Idiom · a fool and his money are soon parted",body:"careless people quickly lose what they have",source:"“Grandma quoted 'a fool and his money are soon parted' when I spent my whole allowance on stickers in one day.”"},"fg-i1627":{src:"fig:idioms:1627",route:"#/figurative",cta:"More idioms",title:"Idiom · in for a penny, in for a pound",body:"once started, commit to it completely",source:"“We'd already baked one cake for the fair — in for a penny, in for a pound, so we made three.”"},"fg-i1628":{src:"fig:idioms:1628",route:"#/figurative",cta:"More idioms",title:"Idiom · penny for the guy",body:"a child's plea for coins before Bonfire Night",source:"“In her London letter, my pen pal explained asking a penny for the guy every November.”"},"fg-i1629":{src:"fig:idioms:1629",route:"#/figurative",cta:"More idioms",title:"Idiom · a pound of flesh",body:"a debt collected cruelly, whatever the harm",source:"“Charging your sister interest on a borrowed pencil? Don't demand your pound of flesh.”"},"fg-i1630":{src:"fig:idioms:1630",route:"#/figurative",cta:"More idioms",title:"Idiom · the almighty dollar",body:"money treated as the most important thing in life",source:"“That shop cares only about the almighty dollar, Dad grumbled.”"},"fg-i1631":{src:"fig:idioms:1631",route:"#/figurative",cta:"More idioms",title:"Idiom · you get what you pay for",body:"cheap things are usually poor quality",source:"“The bargain backpack ripped in a week — you get what you pay for.”"},"fg-i1632":{src:"fig:idioms:1632",route:"#/figurative",cta:"More idioms",title:"Idiom · a rising tide lifts all boats",body:"when conditions improve, everyone benefits",source:"“When the whole class studies together, a rising tide lifts all boats.”"},"fg-i1633":{src:"fig:idioms:1633",route:"#/figurative",cta:"More idioms",title:"Idiom · all hands on deck",body:"everyone must come and help",source:"“Bake sale tomorrow — all hands on deck in the kitchen tonight!”"},"fg-i1634":{src:"fig:idioms:1634",route:"#/figurative",cta:"More idioms",title:"Idiom · anchors aweigh",body:"we're off; the journey is starting",source:"“Anchors aweigh! Dad called as we pulled out for the state bee.”"},"fg-i1635":{src:"fig:idioms:1635",route:"#/figurative",cta:"More idioms",title:"Idiom · any port in a storm",body:"in trouble, accept whatever help is available",source:"“The library was closed, so we studied in the noisy cafeteria — any port in a storm.”"},"fg-i1636":{src:"fig:idioms:1636",route:"#/figurative",cta:"More idioms",title:"Idiom · batten down the hatches",body:"prepare for coming trouble",source:"“Exam week starts Monday — batten down the hatches.”"},"fg-i1637":{src:"fig:idioms:1637",route:"#/figurative",cta:"More idioms",title:"Idiom · calm before the storm",body:"a quiet period just before trouble begins",source:"“The house is silent while the twins nap — the calm before the storm.”"},"fg-i1638":{src:"fig:idioms:1638",route:"#/figurative",cta:"More idioms",title:"Idiom · chase rainbows",body:"to pursue impossible dreams",source:"“Hoping to win without studying is chasing rainbows.”"},"fg-i1639":{src:"fig:idioms:1639",route:"#/figurative",cta:"More idioms",title:"Idiom · sail close to the wind",body:"to behave riskily, just short of breaking the rules",source:"“Whispering hints during review games sails close to the wind.”"},"fg-i1640":{src:"fig:idioms:1640",route:"#/figurative",cta:"More idioms",title:"Idiom · come hell or high water",body:"no matter what obstacles appear",source:"“Come hell or high water, we'll finish this project by Friday.”"},"fg-i1641":{src:"fig:idioms:1641",route:"#/figurative",cta:"More idioms",title:"Idiom · dead in the water",body:"stopped completely, with no chance of progress",source:"“Without poster board, our science-fair plan was dead in the water.”"},"fg-i1642":{src:"fig:idioms:1642",route:"#/figurative",cta:"More idioms",title:"Idiom · fair winds",body:"a wish for good luck on a journey",source:"“Fair winds! Grandma wrote on the card before our big move.”"},"fg-i1643":{src:"fig:idioms:1643",route:"#/figurative",cta:"More idioms",title:"Idiom · fire and brimstone",body:"fierce warnings about punishment",source:"“The coach's fire-and-brimstone speech about missed practices had us showing up early.”"},"fg-i1644":{src:"fig:idioms:1644",route:"#/figurative",cta:"More idioms",title:"Idiom · full sail",body:"moving ahead at top speed and effort",source:"“With a week left before the deadline, our project team was at full sail.”"},"fg-i1645":{src:"fig:idioms:1645",route:"#/figurative",cta:"More idioms",title:"Idiom · get your sea legs",body:"to adjust to a new, unsteady situation",source:"“Give the new student a week to get her sea legs.”"},"fg-i1646":{src:"fig:idioms:1646",route:"#/figurative",cta:"More idioms",title:"Idiom · go overboard",body:"to do far too much",source:"“One poster for the bee is fine; forty is going overboard.”"},"fg-i1647":{src:"fig:idioms:1647",route:"#/figurative",cta:"More idioms",title:"Idiom · high and dry",body:"stranded and left without help",source:"“Our ride forgot us after practice, leaving us high and dry.”"},"fg-i1648":{src:"fig:idioms:1648",route:"#/figurative",cta:"More idioms",title:"Idiom · in deep water",body:"in serious trouble",source:"“He's in deep water for skipping two rehearsals.”"},"fg-i1649":{src:"fig:idioms:1649",route:"#/figurative",cta:"More idioms",title:"Idiom · in the doldrums",body:"gloomy, listless, and stuck",source:"“Rainy weekends put the whole family in the doldrums.”"},"fg-i1650":{src:"fig:idioms:1650",route:"#/figurative",cta:"More idioms",title:"Idiom · in the offing",body:"likely to happen soon",source:"“With report cards in the offing, everyone suddenly loves homework.”"},"fg-i1651":{src:"fig:idioms:1651",route:"#/figurative",cta:"More idioms",title:"Idiom · jump the shark",body:"to decline by resorting to ridiculous attention-grabbing stunts",source:"“Adding a third mascot? Our school newsletter has jumped the shark, Mom laughed.”"},"fg-i1652":{src:"fig:idioms:1652",route:"#/figurative",cta:"More idioms",title:"Idiom · keel over",body:"to fall over suddenly",source:"“He nearly keeled over after the double-lap relay.”"},"fg-i1653":{src:"fig:idioms:1653",route:"#/figurative",cta:"More idioms",title:"Idiom · learn the ropes",body:"to master the basics of a new job or activity",source:"“The first week of scorekeeping is just learning the ropes.”"},"fg-i1654":{src:"fig:idioms:1654",route:"#/figurative",cta:"More idioms",title:"Idiom · like a ship without a rudder",body:"aimless, with no one steering",source:"“Without a team captain, our quiz club felt like a ship without a rudder.”"},"fg-i1655":{src:"fig:idioms:1655",route:"#/figurative",cta:"More idioms",title:"Idiom · miss the tide",body:"to lose an opportunity by acting too late",source:"“Sign up today — if we miss the tide, the workshop fills up.”"},"fg-i1656":{src:"fig:idioms:1656",route:"#/figurative",cta:"More idioms",title:"Idiom · nail your colors to the mast",body:"to declare your position openly and refuse to back down",source:"“She nailed her colors to the mast and defended the new library rules at assembly.”"},"fg-i1657":{src:"fig:idioms:1657",route:"#/figurative",cta:"More idioms",title:"Idiom · on an even keel",body:"steady, calm, and balanced",source:"“Weekly checklists keep our homework on an even keel.”"},"fg-i1658":{src:"fig:idioms:1658",route:"#/figurative",cta:"More idioms",title:"Idiom · on deck",body:"next in line and ready to go",source:"“Finish your word, Maya — you're on deck for round two.”"},"fg-i1659":{src:"fig:idioms:1659",route:"#/figurative",cta:"More idioms",title:"Idiom · push the boat out",body:"to spend generously on a celebration",source:"“For the bee victory, Mum really pushed the boat out — balloons, cake, the lot.”"},"fg-i1660":{src:"fig:idioms:1660",route:"#/figurative",cta:"More idioms",title:"Idiom · rain on your parade",body:"to spoil someone's happy plans",source:"“I hate to rain on your parade, but the field trip moved to March.”"},"fg-i1661":{src:"fig:idioms:1661",route:"#/figurative",cta:"More idioms",title:"Idiom · ride out the storm",body:"to endure trouble until it passes",source:"“We rode out the cafeteria chaos in a quiet corner of the library.”"},"fg-i1662":{src:"fig:idioms:1662",route:"#/figurative",cta:"More idioms",title:"Idiom · run a tight ship",body:"to manage something strictly and efficiently",source:"“Ms. Alvarez runs a tight ship — pencils sharpened before the bell.”"},"fg-i1663":{src:"fig:idioms:1663",route:"#/figurative",cta:"More idioms",title:"Idiom · sail through",body:"to succeed at something with ease",source:"“She sailed through the qualifying round without one wrong letter.”"},"fg-i1664":{src:"fig:idioms:1664",route:"#/figurative",cta:"More idioms",title:"Idiom · a shot across the bow",body:"a warning before serious action is taken",source:"“Dad's 'quiet down back there' was just a shot across the bow.”"},"fg-i1665":{src:"fig:idioms:1665",route:"#/figurative",cta:"More idioms",title:"Idiom · sink or swim",body:"succeed by your own effort or fail completely",source:"“No practice rounds at this bee — it's sink or swim.”"},"fg-i1666":{src:"fig:idioms:1666",route:"#/figurative",cta:"More idioms",title:"Idiom · smooth sailing",body:"easy progress with no problems",source:"“After the tricky first paragraph, the essay was smooth sailing.”"},"fg-i1667":{src:"fig:idioms:1667",route:"#/figurative",cta:"More idioms",title:"Idiom · steer clear of",body:"to carefully avoid",source:"“Steer clear of the wet paint outside the gym.”"},"fg-i1668":{src:"fig:idioms:1668",route:"#/figurative",cta:"More idioms",title:"Idiom · take the wind out of your sails",body:"to suddenly drain someone's confidence or momentum",source:"“The surprise tie-breaker word took the wind out of his sails.”"},"fg-i1669":{src:"fig:idioms:1669",route:"#/figurative",cta:"More idioms",title:"Idiom · test the waters",body:"to try something cautiously before committing",source:"“She tested the waters with one small practice bee before entering regionals.”"},"fg-i1670":{src:"fig:idioms:1670",route:"#/figurative",cta:"More idioms",title:"Idiom · that ship has sailed",body:"the chance is gone for good",source:"“Want to switch project topics now? That ship has sailed.”"},"fg-i1671":{src:"fig:idioms:1671",route:"#/figurative",cta:"More idioms",title:"Idiom · the coast is clear",body:"no one is watching; it is safe to act",source:"“The coast is clear — hide Mom's birthday present now!”"},"fg-i1672":{src:"fig:idioms:1672",route:"#/figurative",cta:"More idioms",title:"Idiom · three sheets to the wind",body:"very drunk and unsteady",source:"“Grandpa joked that the wobbly party robot looked three sheets to the wind.”"},"fg-i1673":{src:"fig:idioms:1673",route:"#/figurative",cta:"More idioms",title:"Idiom · tide over",body:"to help someone through a short difficulty",source:"“A granola bar tided me over until dinner.”"},"fg-i1674":{src:"fig:idioms:1674",route:"#/figurative",cta:"More idioms",title:"Idiom · uncharted waters",body:"a completely unfamiliar situation",source:"“Coaching her little brother put Maya in uncharted waters.”"},"fg-i1675":{src:"fig:idioms:1675",route:"#/figurative",cta:"More idioms",title:"Idiom · walk the plank",body:"to be forced out and take the punishment",source:"“Miss a deadline at that strict newspaper and you walk the plank, Dad joked.”"},"fg-i1676":{src:"fig:idioms:1676",route:"#/figurative",cta:"More idioms",title:"Idiom · water over the dam",body:"past events that cannot be changed",source:"“The missed field trip is water over the dam; let's plan the next one.”"},"fg-i1677":{src:"fig:idioms:1677",route:"#/figurative",cta:"More idioms",title:"Idiom · when it rains, it pours",body:"troubles tend to arrive all at once",source:"“Lost homework, a flat bike tire, hiccups at the bee — when it rains, it pours.”"},"fg-i1678":{src:"fig:idioms:1678",route:"#/figurative",cta:"More idioms",title:"Idiom · whistle for the wind",body:"to wait or wish for something that will not come",source:"“Expecting snow in July? You can whistle for the wind.”"},"fg-i1679":{src:"fig:idioms:1679",route:"#/figurative",cta:"More idioms",title:"Idiom · wind in your sails",body:"encouragement that speeds you along",source:"“The judges' applause put fresh wind in her sails.”"},"fg-i1680":{src:"fig:idioms:1680",route:"#/figurative",cta:"More idioms",title:"Idiom · a storm is brewing",body:"trouble is building and will soon break out",source:"“Two captains and one ball — a storm is brewing at recess.”"},"fg-i1681":{src:"fig:idioms:1681",route:"#/figurative",cta:"More idioms",title:"Idiom · brainstorm",body:"to pour out ideas together quickly",source:"“Let's brainstorm science-fair topics over dinner.”"},"fg-i1682":{src:"fig:idioms:1682",route:"#/figurative",cta:"More idioms",title:"Idiom · a cloud on the horizon",body:"a small sign of coming trouble",source:"“The only cloud on the horizon is Friday's dentist appointment.”"},"fg-i1683":{src:"fig:idioms:1683",route:"#/figurative",cta:"More idioms",title:"Idiom · fair-weather sailor",body:"someone who joins in only when things are easy",source:"“He's a fair-weather sailor — first to quit when practice gets hard.”"},"fg-i1684":{src:"fig:idioms:1684",route:"#/figurative",cta:"More idioms",title:"Idiom · fog of war",body:"the confusion that hides what is really happening",source:"“With three group chats arguing about the schedule, the fog of war set in.”"},"fg-i1685":{src:"fig:idioms:1685",route:"#/figurative",cta:"More idioms",title:"Idiom · lightning never strikes twice",body:"the same rare misfortune will not happen again",source:"“Misspell 'rhythm' twice? Relax — lightning never strikes twice.”"},"fg-i1686":{src:"fig:idioms:1686",route:"#/figurative",cta:"More idioms",title:"Idiom · perfect storm",body:"a rare mix of events that makes a disaster far worse",source:"“Late bus, forgotten lunch, surprise quiz — a perfect storm of a Monday.”"},"fg-i1687":{src:"fig:idioms:1687",route:"#/figurative",cta:"More idioms",title:"Idiom · a snowball's chance",body:"no chance at all",source:"“Our team has a snowball's chance of winning without practicing.”"},"fg-i1688":{src:"fig:idioms:1688",route:"#/figurative",cta:"More idioms",title:"Idiom · snowed under",body:"overwhelmed with too much work",source:"“I'm snowed under with book reports this week.”"},"fg-i1689":{src:"fig:idioms:1689",route:"#/figurative",cta:"More idioms",title:"Idiom · take a rain check",body:"to politely postpone an offer until later",source:"“Can I take a rain check on the sleepover? The bee is tomorrow.”"},"fg-i1690":{src:"fig:idioms:1690",route:"#/figurative",cta:"More idioms",title:"Idiom · throw caution to the winds",body:"to stop being careful and take a bold risk",source:"“She threw caution to the winds and entered the older kids' division.”"},"fg-i1691":{src:"fig:idioms:1691",route:"#/figurative",cta:"More idioms",title:"Idiom · under a cloud",body:"under suspicion or out of favor",source:"“After the missing-snacks mystery, the class hamster was under a cloud.”"},"fg-i1692":{src:"fig:idioms:1692",route:"#/figurative",cta:"More idioms",title:"Idiom · an ace up your sleeve",body:"a hidden advantage saved for the right moment",source:"“Her ace up her sleeve was knowing every Greek root on the list.”"},"fg-i1693":{src:"fig:idioms:1693",route:"#/figurative",cta:"More idioms",title:"Idiom · across the finish line",body:"completed at last",source:"“One more chapter and my reading log is across the finish line.”"},"fg-i1694":{src:"fig:idioms:1694",route:"#/figurative",cta:"More idioms",title:"Idiom · ahead of the game",body:"better prepared or positioned than expected",source:"“Doing Monday's homework on Saturday keeps me ahead of the game.”"},"fg-i1695":{src:"fig:idioms:1695",route:"#/figurative",cta:"More idioms",title:"Idiom · at this stage of the game",body:"at this point in the process",source:"“At this stage of the game, changing topics would sink our project.”"},"fg-i1696":{src:"fig:idioms:1696",route:"#/figurative",cta:"More idioms",title:"Idiom · back in the saddle",body:"back at a familiar activity after a break",source:"“After spring break, it's back in the saddle with morning word drills.”"},"fg-i1697":{src:"fig:idioms:1697",route:"#/figurative",cta:"More idioms",title:"Idiom · ball of confusion",body:"a situation of total chaos",source:"“Move-in day was a ball of confusion until Mom made a checklist.”"},"fg-i1698":{src:"fig:idioms:1698",route:"#/figurative",cta:"More idioms",title:"Idiom · bat a thousand",body:"to succeed every single time",source:"“She's batting a thousand on spelling quizzes this term.”"},"fg-i1699":{src:"fig:idioms:1699",route:"#/figurative",cta:"More idioms",title:"Idiom · behind the play",body:"away from the main action; failing to keep up",source:"“Skim the class group chat daily or you'll be behind the play.”"},"fg-i1700":{src:"fig:idioms:1700",route:"#/figurative",cta:"More idioms",title:"Idiom · blindside",body:"to hit or surprise someone from an unseen direction",source:"“The pop quiz blindsided everyone but Priya.”"},"fg-i1701":{src:"fig:idioms:1701",route:"#/figurative",cta:"More idioms",title:"Idiom · bowl a googly",body:"to surprise someone with a tricky, unexpected question or problem",source:"“The interviewer bowled me a googly: 'Spell your favorite word backward.'”"},"fg-i1702":{src:"fig:idioms:1702",route:"#/figurative",cta:"More idioms",title:"Idiom · bowl over",body:"to astonish someone completely",source:"“Her flawless final round bowled the judges over.”"},"fg-i1703":{src:"fig:idioms:1703",route:"#/figurative",cta:"More idioms",title:"Idiom · call the play",body:"to decide what the group does next",source:"“For the bake sale, Mom calls the play and we follow.”"},"fg-i1704":{src:"fig:idioms:1704",route:"#/figurative",cta:"More idioms",title:"Idiom · carry the ball",body:"to take the main responsibility for getting something done",source:"“Jaden carried the ball on our group's slideshow.”"},"fg-i1705":{src:"fig:idioms:1705",route:"#/figurative",cta:"More idioms",title:"Idiom · checkmate",body:"a final move that leaves an opponent no escape",source:"“Signing up early was checkmate — no one could claim her favorite topic.”"},"fg-i1706":{src:"fig:idioms:1706",route:"#/figurative",cta:"More idioms",title:"Idiom · curveball",body:"an unexpected problem or tricky surprise",source:"“The essay question threw us a real curveball.”"},"fg-i1707":{src:"fig:idioms:1707",route:"#/figurative",cta:"More idioms",title:"Idiom · the dice are loaded",body:"the situation is secretly rigged against you",source:"“With judges from their own school, our team felt the dice were loaded.”"},"fg-i1708":{src:"fig:idioms:1708",route:"#/figurative",cta:"More idioms",title:"Idiom · down for the count",body:"defeated or too exhausted to continue",source:"“After hosting the sleepover, Dad was down for the count by eight.”"},"fg-i1709":{src:"fig:idioms:1709",route:"#/figurative",cta:"More idioms",title:"Idiom · drop the gloves",body:"to abandon politeness and compete in earnest",source:"“The two debate teams dropped the gloves in the final round.”"},"fg-i1710":{src:"fig:idioms:1710",route:"#/figurative",cta:"More idioms",title:"Idiom · even the score",body:"to get revenge or make things equal again",source:"“She evened the score in the rematch with a perfect round.”"},"fg-i1711":{src:"fig:idioms:1711",route:"#/figurative",cta:"More idioms",title:"Idiom · fair play",body:"honest, rule-following treatment of everyone",source:"“The team returned the trophy — fair play matters more than winning.”"},"fg-i1712":{src:"fig:idioms:1712",route:"#/figurative",cta:"More idioms",title:"Idiom · first out of the gate",body:"the quickest to start",source:"“Maya was first out of the gate with her science-fair form.”"},"fg-i1713":{src:"fig:idioms:1713",route:"#/figurative",cta:"More idioms",title:"Idiom · fumble the ball",body:"to clumsily ruin an opportunity",source:"“I knew the word but fumbled the ball by rushing.”"},"fg-i1714":{src:"fig:idioms:1714",route:"#/figurative",cta:"More idioms",title:"Idiom · game changer",body:"something that transforms a situation completely",source:"“Flashcards on the bus were a game changer for my practice time.”"},"fg-i1715":{src:"fig:idioms:1715",route:"#/figurative",cta:"More idioms",title:"Idiom · game plan",body:"a strategy worked out in advance",source:"“Our study game plan: roots on Monday, review on Friday.”"},"fg-i1716":{src:"fig:idioms:1716",route:"#/figurative",cta:"More idioms",title:"Idiom · get a head start",body:"to begin before others and gain an advantage",source:"“Waking up early gave me a head start on the word list.”"},"fg-i1717":{src:"fig:idioms:1717",route:"#/figurative",cta:"More idioms",title:"Idiom · get the show on the road",body:"to finally start an activity or journey",source:"“Grab your backpacks — let's get this show on the road.”"},"fg-i1718":{src:"fig:idioms:1718",route:"#/figurative",cta:"More idioms",title:"Idiom · give it your best shot",body:"to try as hard as you possibly can",source:"“Even if 'chiaroscuro' looks scary, give it your best shot.”"},"fg-i1719":{src:"fig:idioms:1719",route:"#/figurative",cta:"More idioms",title:"Idiom · go for gold",body:"to aim for the very top prize",source:"“This year she's going for gold at the national bee.”"},"fg-i1720":{src:"fig:idioms:1720",route:"#/figurative",cta:"More idioms",title:"Idiom · go to bat for someone",body:"to defend or support someone actively",source:"“Mom went to bat for me when the schedule clashed with the bee.”"},"fg-i1721":{src:"fig:idioms:1721",route:"#/figurative",cta:"More idioms",title:"Idiom · in due course",body:"at the proper time, after the usual wait",source:"“The principal promised the science-fair results would be announced in due course.”"},"fg-i1722":{src:"fig:idioms:1722",route:"#/figurative",cta:"More idioms",title:"Idiom · in the long run",body:"over a long time; eventually",source:"“Reading every night feels slow, but in the long run it builds a huge vocabulary.”"},"fg-i1723":{src:"fig:idioms:1723",route:"#/figurative",cta:"More idioms",title:"Idiom · in the short term",body:"during the near future",source:"“In the short term we'll rent skates, and buy a pair if Lena stays keen.”"},"fg-i1724":{src:"fig:idioms:1724",route:"#/figurative",cta:"More idioms",title:"Idiom · kill time",body:"to pass empty time with idle amusements",source:"“We killed time before the recital with twenty questions.”"},"fg-i1725":{src:"fig:idioms:1725",route:"#/figurative",cta:"More idioms",title:"Idiom · like clockwork",body:"smoothly, regularly, and precisely on schedule",source:"“Every Saturday, like clockwork, Grandma calls at nine for our spelling game.”"},"fg-i1726":{src:"fig:idioms:1726",route:"#/figurative",cta:"More idioms",title:"Idiom · make up for lost time",body:"to hurry or do extra after a delay",source:"“After a week of flu, Omar studied all weekend to make up for lost time.”"},"fg-i1727":{src:"fig:idioms:1727",route:"#/figurative",cta:"More idioms",title:"Idiom · moment of truth",body:"the instant when something is finally put to the test",source:"“The judges opened the envelope — the moment of truth for our robotics team.”"},"fg-i1728":{src:"fig:idioms:1728",route:"#/figurative",cta:"More idioms",title:"Idiom · never in a million years",body:"absolutely never",source:"“Never in a million years did I think I'd out-spell an eighth grader.”"},"fg-i1729":{src:"fig:idioms:1729",route:"#/figurative",cta:"More idioms",title:"Idiom · nine-day wonder",body:"a sensation everyone talks about, then quickly forgets",source:"“The cafeteria's robot server was a nine-day wonder; by October nobody looked up.”"},"fg-i1730":{src:"fig:idioms:1730",route:"#/figurative",cta:"More idioms",title:"Idiom · now or never",body:"act immediately or lose the chance forever",source:"“Sign-ups close at noon, so it's now or never for the talent show.”"},"fg-i1731":{src:"fig:idioms:1731",route:"#/figurative",cta:"More idioms",title:"Idiom · on borrowed time",body:"living or lasting longer than expected, with the end near",source:"“Our wheezing old washing machine is on borrowed time, Dad says.”"},"fg-i1732":{src:"fig:idioms:1732",route:"#/figurative",cta:"More idioms",title:"Idiom · on the dot",body:"exactly on time",source:"“The bus leaves at 7:45 on the dot, with or without you.”"},"fg-i1733":{src:"fig:idioms:1733",route:"#/figurative",cta:"More idioms",title:"Idiom · on the spur of the moment",body:"suddenly, without any planning",source:"“On the spur of the moment, Mom pulled over for roadside strawberries.”"},"fg-i1734":{src:"fig:idioms:1734",route:"#/figurative",cta:"More idioms",title:"Idiom · once in a lifetime",body:"so rare it may happen only once in your life",source:"“Watching the total eclipse from the schoolyard felt once in a lifetime.”"},"fg-i1735":{src:"fig:idioms:1735",route:"#/figurative",cta:"More idioms",title:"Idiom · pressed for time",body:"in a rush, with barely enough time",source:"“Pressed for time, Ava ate breakfast while quizzing herself on prefixes.”"},"fg-i1736":{src:"fig:idioms:1736",route:"#/figurative",cta:"More idioms",title:"Idiom · second wind",body:"a burst of fresh energy after feeling exhausted",source:"“Halfway through cleaning her room, Jo caught a second wind and finished the closet too.”"},"fg-i1737":{src:"fig:idioms:1737",route:"#/figurative",cta:"More idioms",title:"Idiom · stand the test of time",body:"to remain good, true, or popular for many years",source:"“Grandma's chocolate-chip recipe has stood the test of time for forty years.”"},"fg-i1738":{src:"fig:idioms:1738",route:"#/figurative",cta:"More idioms",title:"Idiom · take your time",body:"go as slowly and carefully as you need",source:"“'Take your time,' the judge said, and Leo spelled each letter slowly.”"},"fg-i1739":{src:"fig:idioms:1739",route:"#/figurative",cta:"More idioms",title:"Idiom · moment of glory",body:"a brief time of shining success and admiration",source:"“Holding the trophy overhead was Sam's moment of glory.”"},"fg-i1740":{src:"fig:idioms:1740",route:"#/figurative",cta:"More idioms",title:"Idiom · third time's the charm",body:"the third attempt often succeeds after two failures",source:"“Ella missed 'rhythm' twice in practice, but third time's the charm — she nailed it.”"},"fg-i1741":{src:"fig:idioms:1741",route:"#/figurative",cta:"More idioms",title:"Idiom · time after time",body:"repeatedly; again and again",source:"“Time after time, Dad reminds us to charge the tablet before car trips.”"},"fg-i1742":{src:"fig:idioms:1742",route:"#/figurative",cta:"More idioms",title:"Idiom · to be under someone's blanket",body:"to be secretly plotting together with someone",source:"“The twins were under one blanket all week, planning Dad's surprise party.”"},"fg-i1743":{src:"fig:idioms:1743",route:"#/figurative",cta:"More idioms",title:"Idiom · the wolf's pup becomes a wolf",body:"children grow up to have their parents' nature",source:"“Coach smiled 'the wolf's pup becomes a wolf' when the champion sprinter's daughter won her first race.”"},"fg-i1744":{src:"fig:idioms:1744",route:"#/figurative",cta:"More idioms",title:"Idiom · to become an eggplant",body:"to turn deep purple from embarrassment, cold, or a bruise",source:"“When the whole class sang happy birthday to her, Ayşe became an eggplant.”"},"fg-i1745":{src:"fig:idioms:1745",route:"#/figurative",cta:"More idioms",title:"Idiom · cheap meat's broth is tasteless",body:"skimping on quality brings disappointing results",source:"“The bargain glue let my whole diorama collapse — cheap meat's broth is tasteless, Dad sighed.”"},"fg-i1746":{src:"fig:idioms:1746",route:"#/figurative",cta:"More idioms",title:"Idiom · to raise dust",body:"to kick up a big fuss or commotion",source:"“My sister raised dust in the kitchen when her last cookie went missing.”"},"fg-i1747":{src:"fig:idioms:1747",route:"#/figurative",cta:"More idioms",title:"Idiom · to walk with wooden shoes on thin ice",body:"to charge clumsily into a delicate situation",source:"“Asking the teacher to cancel homework on test week was walking with wooden shoes on thin ice.”"},"fg-i1748":{src:"fig:idioms:1748",route:"#/figurative",cta:"More idioms",title:"Idiom · to fall between two chairs",body:"to miss out on both options by fitting neither",source:"“Signing up late, Leo fell between two chairs: both the chess club and the art club were already full.”"},"fg-i1749":{src:"fig:idioms:1749",route:"#/figurative",cta:"More idioms",title:"Idiom · to swallow a camel",body:"to reluctantly accept something you strongly dislike",source:"“Sharing a room with my messy brother on vacation — I swallowed a camel.”"},"fg-i1750":{src:"fig:idioms:1750",route:"#/figurative",cta:"More idioms",title:"Idiom · time and tide wait for no man",body:"time moves on whether you are ready, so act now",source:"“Grandpa tapped his watch before the museum trip: 'Time and tide wait for no man.'”"},"fg-i1751":{src:"fig:idioms:1751",route:"#/figurative",cta:"More idioms",title:"Idiom · time heals all wounds",body:"sadness and hurt fade as time passes",source:"“Losing the finals stung, but time heals all wounds — by summer Lena was laughing about it.”"},"fg-i1752":{src:"fig:idioms:1752",route:"#/figurative",cta:"More idioms",title:"Idiom · time on your hands",body:"spare time with nothing to do",source:"“With homework done early, Marcus had time on his hands to build a card tower.”"},"fg-i1753":{src:"fig:idioms:1753",route:"#/figurative",cta:"More idioms",title:"Idiom · time will tell",body:"only the future will reveal the truth",source:"“Will the new study app help? Time will tell at report cards.”"},"fg-i1754":{src:"fig:idioms:1754",route:"#/figurative",cta:"More idioms",title:"Idiom · turn back the clock",body:"to return to an earlier time or its ways",source:"“Grandma says school dances turn back the clock to her own gym-hall days.”"},"fg-i1755":{src:"fig:idioms:1755",route:"#/figurative",cta:"More idioms",title:"Idiom · two shakes of a lamb's tail",body:"a very short time; almost instantly",source:"“'Dinner's ready in two shakes of a lamb's tail,' Dad called from the kitchen.”"},"fg-i1756":{src:"fig:idioms:1756",route:"#/figurative",cta:"More idioms",title:"Idiom · behind schedule",body:"later than the planned timetable",source:"“The bake sale started behind schedule because the cupcakes were still cooling.”"},"fg-i1757":{src:"fig:idioms:1757",route:"#/figurative",cta:"More idioms",title:"Idiom · at sixes and sevens",body:"in total confusion or disarray",source:"“On the first day back, the classroom was at sixes and sevens — wrong desks, lost pencils, missing hamster.”"},"fg-i1758":{src:"fig:idioms:1758",route:"#/figurative",cta:"More idioms",title:"Idiom · forty winks",body:"a short nap",source:"“Grandpa grabs forty winks in his armchair before dinner.”"},"fg-i1759":{src:"fig:idioms:1759",route:"#/figurative",cta:"More idioms",title:"Idiom · give me five",body:"slap my palm to celebrate or say hello",source:"“'Give me five!' cheered Dad when Zoe read her first chapter book alone.”"},"fg-i1760":{src:"fig:idioms:1760",route:"#/figurative",cta:"More idioms",title:"Idiom · high five",body:"a celebration slap of two raised palms",source:"“The whole team lined up for high fives after the quiz-bowl win.”"},"fg-i1761":{src:"fig:idioms:1761",route:"#/figurative",cta:"More idioms",title:"Idiom · nine times out of ten",body:"almost always",source:"“Nine times out of ten, the missing remote is under Dad's cushion.”"},"fg-i1762":{src:"fig:idioms:1762",route:"#/figurative",cta:"More idioms",title:"Idiom · on all fours",body:"on hands and knees",source:"“We crawled on all fours hunting the hamster behind the couch.”"},"fg-i1763":{src:"fig:idioms:1763",route:"#/figurative",cta:"More idioms",title:"Idiom · one in a million",body:"extraordinarily rare and special",source:"“Teachers like Ms. Rivera, who stays late to coach spellers, are one in a million.”"},"fg-i1764":{src:"fig:idioms:1764",route:"#/figurative",cta:"More idioms",title:"Idiom · seventh heaven",body:"a state of perfect happiness",source:"“Nadia was in seventh heaven when her library hold finally arrived.”"},"fg-i1765":{src:"fig:idioms:1765",route:"#/figurative",cta:"More idioms",title:"Idiom · six feet under",body:"dead and buried",source:"“Grandpa jokes that his ancient flip phone should be six feet under by now.”"},"fg-i1766":{src:"fig:idioms:1766",route:"#/figurative",cta:"More idioms",title:"Idiom · six of one, half a dozen of the other",body:"the two options are exactly the same",source:"“Bus or subway to the museum? Six of one, half a dozen of the other.”"},"fg-i1767":{src:"fig:idioms:1767",route:"#/figurative",cta:"More idioms",title:"Idiom · sixth sense",body:"a mysterious ability to know what the five senses cannot",source:"“Mom's sixth sense always knows when we're sneaking cookies.”"},"fg-i1768":{src:"fig:idioms:1768",route:"#/figurative",cta:"More idioms",title:"Idiom · take five",body:"to take a short break",source:"“'Take five,' said the choir director, 'then we'll run the last verse.'”"},"fg-i1769":{src:"fig:idioms:1769",route:"#/figurative",cta:"More idioms",title:"Idiom · ten a penny",body:"so common it is worth very little",source:"“Rubber-band bracelets are ten a penny at school this term.”"},"fg-i1770":{src:"fig:idioms:1770",route:"#/figurative",cta:"More idioms",title:"Idiom · zero tolerance",body:"a rule punishing every violation, however small",source:"“Our school has zero tolerance for phones during exams.”"},"fg-i1771":{src:"fig:idioms:1771",route:"#/figurative",cta:"More idioms",title:"Idiom · to have a spider on the ceiling",body:"to be a little crazy or wonderfully odd",source:"“Our art teacher wears a different silly hat every day — she has a spider on the ceiling, in the best way.”"},"fg-i1772":{src:"fig:idioms:1772",route:"#/figurative",cta:"More idioms",title:"Idiom · the early morning has gold in its mouth",body:"starting early brings the best rewards",source:"“Grandpa taps my door at seven sharp: the early morning has gold in its mouth, and spelling practice awaits.”"},"fg-i1773":{src:"fig:idioms:1773",route:"#/figurative",cta:"More idioms",title:"Idiom · hunger drives the wolf out of the woods",body:"need forces even the reluctant to act",source:"“An empty snack shelf drove the wolf out of the woods — my brother finally learned to make toast.”"},"fg-i1774":{src:"fig:idioms:1774",route:"#/figurative",cta:"More idioms",title:"Idiom · measure seven times, cut once",body:"check your work carefully before doing something you can't undo",source:"“Measure seven times, cut once: reread every answer before you hand in the test.”"},"fg-i1775":{src:"fig:idioms:1775",route:"#/figurative",cta:"More idioms",title:"Idiom · the quieter you go, the further you get",body:"patience and steadiness carry you farther than rushing",source:"“The quieter you go, the further you get: ten calm minutes of spelling a night beat one frantic hour.”"},"fg-i1776":{src:"fig:idioms:1776",route:"#/figurative",cta:"More idioms",title:"Idiom · a kind word opens iron gates",body:"gentle words can win over even the hardest people",source:"“A kind word opens iron gates — Maya's polite request got our class extra library time.”"},"fg-i1777":{src:"fig:idioms:1777",route:"#/figurative",cta:"More idioms",title:"Idiom · the apple falls under the apple tree",body:"children turn out like their parents",source:"“Mom won her school bee, and now I'm in the final — the apple falls under the apple tree.”"},"fg-i1778":{src:"fig:idioms:1778",route:"#/figurative",cta:"More idioms",title:"Idiom · to make a long face",body:"to look sad or disappointed",source:"“Don't make a long face over one missed word — there's another bee in the spring.”"},"fg-i1779":{src:"fig:idioms:1779",route:"#/figurative",cta:"More idioms",title:"Idiom · a chip on your shoulder",body:"carrying anger and looking for a fight over past unfairness",source:"“Ever since he lost the kickball game, Sam has had a chip on his shoulder at recess.”"},"fg-i1780":{src:"fig:idioms:1780",route:"#/figurative",cta:"More idioms",title:"Idiom · a drop in the bucket",body:"a tiny amount compared to what is needed",source:"“One canned good felt like a drop in the bucket, so our class set a goal of five hundred.”"},"fg-i1781":{src:"fig:idioms:1781",route:"#/figurative",cta:"More idioms",title:"Idiom · a leopard can't change its spots",body:"people can't change their basic nature",source:"“He promised to stop hiding my eraser, but a leopard can't change its spots.”"},"fg-i1782":{src:"fig:idioms:1782",route:"#/figurative",cta:"More idioms",title:"Idiom · a storm in a teacup",body:"a big fuss over something unimportant",source:"“The mix-up over cupcake flavors became a storm in a teacup at the bake sale.”"},"fg-i1783":{src:"fig:idioms:1783",route:"#/figurative",cta:"More idioms",title:"Idiom · against the grain",body:"opposite to what feels natural or usual",source:"“Skipping dessert goes against the grain for my sweet-toothed dad.”"},"fg-i1784":{src:"fig:idioms:1784",route:"#/figurative",cta:"More idioms",title:"Idiom · ahead of the curve",body:"more advanced than most people or the current trend",source:"“Practicing next year's word list put Riya ahead of the curve.”"},"fg-i1785":{src:"fig:idioms:1785",route:"#/figurative",cta:"More idioms",title:"Idiom · air your dirty laundry",body:"to discuss private family problems in public",source:"“Mom says arguments about chores stay home — no airing our dirty laundry at school.”"},"fg-i1786":{src:"fig:idioms:1786",route:"#/figurative",cta:"More idioms",title:"Idiom · all bark and no bite",body:"sounding fierce but never acting on threats",source:"“The gym teacher's growl is all bark and no bite — he hands out stickers after every class.”"},"fg-i1787":{src:"fig:idioms:1787",route:"#/figurative",cta:"More idioms",title:"Idiom · armed to the teeth",body:"carrying every weapon or tool you could possibly need",source:"“Priya arrived at the bee armed to the teeth: dictionaries, flashcards, and three lucky pencils.”"},"fg-i1788":{src:"fig:idioms:1788",route:"#/figurative",cta:"More idioms",title:"Idiom · at the drop of a hat",body:"instantly, without any hesitation",source:"“My grandma will play checkers at the drop of a hat.”"},"fg-i1789":{src:"fig:idioms:1789",route:"#/figurative",cta:"More idioms",title:"Idiom · bail out",body:"to rescue someone from trouble, or escape a failing situation",source:"“Dad bailed me out by driving my forgotten project to school.”"},"fg-i1790":{src:"fig:idioms:1790",route:"#/figurative",cta:"More idioms",title:"Idiom · bank on it",body:"to count on something completely",source:"“Rain or shine, Ms. Lee gives a Friday quiz — you can bank on it.”"},"fg-i1791":{src:"fig:idioms:1791",route:"#/figurative",cta:"More idioms",title:"Idiom · bear fruit",body:"to produce good results after long effort",source:"“Months of flashcards bore fruit when Ana aced the regional bee.”"},"fg-i1792":{src:"fig:idioms:1792",route:"#/figurative",cta:"More idioms",title:"Idiom · beat a dead horse",body:"to keep arguing something already settled or hopeless",source:"“Asking for a dog again after Mom's tenth no is beating a dead horse.”"},"fg-i1793":{src:"fig:idioms:1793",route:"#/figurative",cta:"More idioms",title:"Idiom · behind the eight ball",body:"stuck in a difficult position with no easy escape",source:"“Losing my word list the night before the quiz put me behind the eight ball.”"},"fg-i1794":{src:"fig:idioms:1794",route:"#/figurative",cta:"More idioms",title:"Idiom · below the belt",body:"unfair or hurtful beyond acceptable limits",source:"“Teasing him about his stutter was below the belt.”"},"fg-i1795":{src:"fig:idioms:1795",route:"#/figurative",cta:"More idioms",title:"Idiom · bet your bottom dollar",body:"to be absolutely certain about something",source:"“You can bet your bottom dollar Grandpa will be in the front row at the bee.”"},"fg-i1796":{src:"fig:idioms:1796",route:"#/figurative",cta:"More idioms",title:"Idiom · bird's-eye view",body:"a view of everything from high above",source:"“From the ferris wheel we had a bird's-eye view of the whole school fair.”"},"fg-i1797":{src:"fig:idioms:1797",route:"#/figurative",cta:"More idioms",title:"Idiom · bitter pill to swallow",body:"an unpleasant fact that must be accepted",source:"“Losing the final by one letter was a bitter pill to swallow.”"},"fg-i1798":{src:"fig:idioms:1798",route:"#/figurative",cta:"More idioms",title:"Idiom · blood is thicker than water",body:"family bonds come before all others",source:"“Cousins squabble all afternoon, but blood is thicker than water the moment someone else picks on one of them.”"},"fg-i1799":{src:"fig:idioms:1799",route:"#/figurative",cta:"More idioms",title:"Idiom · blow your own trumpet",body:"to brag about your own achievements",source:"“Not to blow my own trumpet, but I spelled every word right this week.”"},"fg-i1800":{src:"fig:idioms:1800",route:"#/figurative",cta:"More idioms",title:"Idiom · break new ground",body:"to do something never done before",source:"“Our class broke new ground with the school's first student podcast.”"},"fg-i1801":{src:"fig:idioms:1801",route:"#/figurative",cta:"More idioms",title:"Idiom · breathe down someone's neck",body:"to watch someone so closely it makes them uncomfortable",source:"“I can't practice piano with my brother breathing down my neck.”"},"fg-i1802":{src:"fig:idioms:1802",route:"#/figurative",cta:"More idioms",title:"Idiom · bring to the table",body:"to offer useful skills or ideas to a group",source:"“Marcus brings calm nerves and a huge vocabulary to our quiz-bowl team.”"},"fg-i1803":{src:"fig:idioms:1803",route:"#/figurative",cta:"More idioms",title:"Idiom · brownie points",body:"small credits earned for pleasing someone",source:"“Wiping the whiteboard without being asked earned me brownie points with Ms. Cho.”"},"fg-i1804":{src:"fig:idioms:1804",route:"#/figurative",cta:"More idioms",title:"Idiom · burn a hole in your pocket",body:"money you feel desperate to spend right away",source:"“My birthday money burned a hole in my pocket until the book fair opened.”"},"fg-i1805":{src:"fig:idioms:1805",route:"#/figurative",cta:"More idioms",title:"Idiom · carry the torch",body:"to keep loyally supporting a cause or quietly loving someone",source:"“Years after graduating, Dad still carries the torch for his old school's spelling team.”"},"fg-i1806":{src:"fig:idioms:1806",route:"#/figurative",cta:"More idioms",title:"Idiom · carte blanche",body:"complete freedom to do whatever you choose",source:"“Mom gave me carte blanche to decorate my side of the room.”"},"fg-i1807":{src:"fig:idioms:1807",route:"#/figurative",cta:"More idioms",title:"Idiom · cash cow",body:"a business or product that reliably makes money",source:"“The lemonade stand became the twins' cash cow every summer.”"},"fg-i1808":{src:"fig:idioms:1808",route:"#/figurative",cta:"More idioms",title:"Idiom · cast a wide net",body:"to try many options or ask many people",source:"“Casting a wide net, Zoe invited every fourth grader to join the new club.”"},"fg-i1809":{src:"fig:idioms:1809",route:"#/figurative",cta:"More idioms",title:"Idiom · cat and mouse",body:"a game of chasing, escaping, and outwitting",source:"“Tag at recess turned into cat and mouse between Leo and the twins.”"},"fg-i1810":{src:"fig:idioms:1810",route:"#/figurative",cta:"More idioms",title:"Idiom · cat nap",body:"a short light sleep",source:"“Dad takes a cat nap before driving us to evening practice.”"},"fg-i1811":{src:"fig:idioms:1811",route:"#/figurative",cta:"More idioms",title:"Idiom · champ at the bit",body:"to be impatient to start",source:"“The spellers were champing at the bit while the judges tested the microphone.”"},"fg-i1812":{src:"fig:idioms:1812",route:"#/figurative",cta:"More idioms",title:"Idiom · change of heart",body:"a reversal of your feelings or decision",source:"“Mia had a change of heart and shared her cupcake after all.”"},"fg-i1813":{src:"fig:idioms:1813",route:"#/figurative",cta:"More idioms",title:"Idiom · cherry-pick",body:"to choose only the best or most convenient bits",source:"“You can't cherry-pick only the easy words to practice.”"},"fg-i1814":{src:"fig:idioms:1814",route:"#/figurative",cta:"More idioms",title:"Idiom · chew the fat",body:"to chat in a relaxed, unhurried way",source:"“Grandpa and his friends chew the fat on the porch every Sunday.”"},"fg-i1815":{src:"fig:idioms:1815",route:"#/figurative",cta:"More idioms",title:"Idiom · chink in the armor",body:"one small weakness in an otherwise strong defense",source:"“Silent letters are the chink in my armor at spelling bees.”"},"fg-i1816":{src:"fig:idioms:1816",route:"#/figurative",cta:"More idioms",title:"Idiom · clean bill of health",body:"official confirmation that everything is fine",source:"“The dentist sent me off with a clean bill of health and a new toothbrush.”"},"fg-i1817":{src:"fig:idioms:1817",route:"#/figurative",cta:"More idioms",title:"Idiom · clip someone's wings",body:"to limit someone's freedom or power",source:"“Losing tablet privileges clipped my brother's wings for the weekend.”"},"fg-i1818":{src:"fig:idioms:1818",route:"#/figurative",cta:"More idioms",title:"Idiom · come full circle",body:"to return to where things began",source:"“Mom came full circle, returning to teach at the very school she attended as a kid.”"},"fg-i1819":{src:"fig:idioms:1819",route:"#/figurative",cta:"More idioms",title:"Idiom · come rain or shine",body:"no matter what happens",source:"“Come rain or shine, Grandma walks me to the bus stop.”"},"fg-i1820":{src:"fig:idioms:1820",route:"#/figurative",cta:"More idioms",title:"Idiom · cook the books",body:"to falsify financial records",source:"“Our class treasurer joked he would never cook the books over bake-sale money.”"},"fg-i1821":{src:"fig:idioms:1821",route:"#/figurative",cta:"More idioms",title:"Idiom · crack the whip",body:"to push people to work harder",source:"“Coach really cracked the whip the week before the tournament.”"},"fg-i1822":{src:"fig:idioms:1822",route:"#/figurative",cta:"More idioms",title:"Idiom · cream of the crop",body:"the very best of a group",source:"“The regional bee gathers the cream of the crop from every school.”"},"fg-i1823":{src:"fig:idioms:1823",route:"#/figurative",cta:"More idioms",title:"Idiom · crunch time",body:"the critical period when everything must get done",source:"“The night before the science fair is crunch time in our kitchen.”"},"fg-i1824":{src:"fig:idioms:1824",route:"#/figurative",cta:"More idioms",title:"Idiom · cut and dried",body:"already decided, with no room for change",source:"“The rules of the bee are cut and dried: misspell a word and you sit down.”"},"fg-i1825":{src:"fig:idioms:1825",route:"#/figurative",cta:"More idioms",title:"Idiom · cut from the same cloth",body:"very similar in character",source:"“My aunt and my mom are cut from the same cloth — both hum while they cook.”"},"fg-i1826":{src:"fig:idioms:1826",route:"#/figurative",cta:"More idioms",title:"Idiom · damp squib",body:"something that fizzles instead of impressing",source:"“The much-hyped magic show was a damp squib — the rabbit never appeared.”"},"fg-i1827":{src:"fig:idioms:1827",route:"#/figurative",cta:"More idioms",title:"Idiom · double-edged sword",body:"something that helps and harms at the same time",source:"“Being the oldest is a double-edged sword: more privileges, more chores.”"}});
